// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 roleIdx, address actor, address target) public {
        vm.assume(actor != address(0) && target != address(0));
        bytes32[3] memory roles = [
            c.TIMELOCK_ADMIN_ROLE(),
            c.PROPOSER_ROLE(),
            c.EXECUTOR_ROLE()
        ];
        bytes32 role = roles[roleIdx % 3];
        bytes32 adminRole = c.getRoleAdmin(role);

        // give actor the admin power over `role` (test contract holds TIMELOCK_ADMIN_ROLE)
        vm.prank(address(this));
        c.grantRole(adminRole, actor);
        assertTrue(c.hasRole(adminRole, actor), "setup: actor must hold admin role");

        // actor renounces the admin role
        vm.prank(actor);
        c.renounceRole(adminRole, actor);

        // GENERAL RULE: renouncing a role revokes it, so a call gated by that role
        // (grantRole requires the role's admin) must now revert for that account.
        vm.prank(actor);
        bool ok;
        try c.grantRole(role, target) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "renounced admin must no longer be able to grantRole");
    }
}
